\section{Identifiability of GRL-SNAM}
\label{app:proof:and:lemma}
\subsection{From optimal control to reduced Hamiltonian dynamics }
\label{app:ocp_to_ham}
\begin{lemma}[Forward: autonomous pure state constraints induce a (reduced) Hamiltonian flow]
\label{thm:forward_state_constrained_pmp_reduced_ham}
Fix a scenario $\mathcal{E}$ and consider the autonomous, control-affine system on an open set
$\mathcal{Q}\subset\mathbb{R}^n$,
\begin{equation}
\dot q(t)=f(q(t)) + A(q(t))u(t),\qquad q(0)=q_0,\qquad q(T)=q_T,
\label{eq:ocp_dyn}
\end{equation}
with pure state inequality constraints
\begin{equation}
d_i(q(t))\ge 0,\qquad i=1,\dots,m,\qquad t\in[0,T],
\label{eq:ocp_state_constraints}
\end{equation}
and objective
\begin{equation}
\min_{u(\cdot)\in\mathcal{U}} \ J(q, u)
:=\int_0^T L(q(t),u(t))\,dt,
\label{eq:ocp_cost}
\end{equation}
where the admissible control set $\mathcal{U}$ consists of measurable $u(\cdot)$ with
$u(t)\in U\subset\mathbb{R}^d$ a.e.

Assume:
\begin{enumerate}
\item $f$ and $A$ are locally Lipschitz on $\mathcal{Q}$.
\item $U$ is nonempty, compact, and convex; $L(\cdot,\cdot)$ is continuous and $C^1$ in $(q,u)$.
\item (Existence) There exists an optimal pair $(q^\star(\cdot),u^\star(\cdot))$ satisfying
\cref{eq:ocp_dyn} and \cref{eq:ocp_state_constraints}.
\item (Regularity / qualification) Each $d_i\in C^2(\mathcal{Q})$ and along boundary arcs the active constraint
gradients satisfy a standard constraint qualification (e.g.\ linear independence of
$\{\nabla d_i(q^\star(t))\}_{i\in\mathcal{A}(t)}$ and a feasible-direction condition), so that the
state-constrained maximum principle applies.
\end{enumerate}

Define the \emph{control Hamiltonian} as \textit{Fenchel Coupling}
\begin{equation}
\mathcal{H}_c(q,p,u):=\langle f(q)+A(q)u, p\rangle-L(q,u).
\label{eq:def_control_ham}
\end{equation}
Then there exist:
(i) a costate $p:[0,T]\to\mathbb{R}^n$ of bounded variation(\textbf{BV}, right-continuous with left limits),
and (ii) nonnegative finite Radon measures $\{\mu_i\}_{i=1}^m$ on $[0,T]$,
such that the following hold:

\smallskip
\noindent\textbf{(i) Maximum condition (a.e.).}
For almost every $t\in[0,T]$,
\begin{equation}
u^\star(t)\in \arg\max_{u\in U}\ \mathcal{H}_c\big(q^\star(t),p(t),u\big).
\label{eq:max_condition}
\end{equation}
\noindent\textbf{(ii) State equation.}
For a.e.\ $t$,
\begin{equation}
\dot q^\star(t)=\nabla_p \mathcal{H}_c\big(q^\star(t),p(t),u^\star(t)\big)
= f(q^\star(t))+A(q^\star(t))u^\star(t).
\label{eq:state_eq_from_ham}
\end{equation}
\noindent\textbf{(iii) Adjoint equation in measure form.}
As an equality of $\mathbb{R}^n$-valued measures on $[0,T]$,
\begin{equation}
dp(t)= -\nabla_q \mathcal{H}_c\big(q^\star(t),p(t),u^\star(t)\big)\,dt
\;-\;\sum_{i=1}^m \nabla d_i\big(q^\star(t)\big)\,\mu_i(dt).
\label{eq:adjoint_measure}
\end{equation}
Equivalently, for all $0\le t_0<t_1\le T$,
\begin{equation}
p(t_1^+)-p(t_0^-)
= -\int_{t_0}^{t_1}\nabla_q \mathcal{H}_c\big(q^\star(t),p(t),u^\star(t)\big)\,dt
\;-\;\sum_{i=1}^m \int_{(t_0,t_1]} \nabla d_i\big(q^\star(t)\big)\,\mu_i(dt).
\label{eq:adjoint_integral}
\end{equation}
\noindent\textbf{(iv) Complementarity / support.}
Each $\mu_i$ is supported on the active set:
\begin{equation}
\mathrm{supp}(\mu_i)\subset \{t\in[0,T]: d_i(q^\star(t))=0\},
\qquad\text{i.f.f.}\qquad
\int_{[0,T]} d_i(q^\star(t))\,\mu_i(dt)=0.
\label{eq:complementarity_measure}
\end{equation}
\noindent\textbf{(iv) Reduced Hamiltonian.} Assume in addition that the running cost decomposes as
\begin{equation}
L(q,u)=\varphi(u)+V(q),
\qquad\text{with $\varphi$ proper, closed, strictly convex, and $C^1$, and $V\in C^1(\mathcal Q)$.}
\label{eq:cost_split_B_statecon}
\end{equation}
Then the maximizer $u^\star(q,p)$ in \cref{eq:max_condition} is unique (up to the compact control constraint $U$),
and the reduced PMP Hamiltonian depends only on $(q,p)$:
\begin{equation}
\label{eq:def_reduced_ham_pmp_statecon}
H_{\mathrm{PMP}}(q,p)
:=\sup_{u\in U}\mathcal H_c(q,p,u)
=\sup_{u\in U}\big\{p^\top A(q)u-\varphi(u)\big\}+p^\top f(q)-V(q).
\end{equation}
Hence \cref{eq:state_eq_from_ham} and \cref{eq:adjoint_measure} can be restated without explicit dependency on $u^\star$.
\end{lemma}

\begin{proof}
We present the derivation in steps and refer readers Theorem 4.2 in \cite{hartl1995survey} for further discussions. The proof contains major steps including reducing the general state-constrained PMP statement
to the present autonomous, pure-state-constraint setting and then eliminating $u$ via conjugacy.

\smallskip
\noindent\textbf{Step 1 (Apply the state-constrained maximum principle).}
Under assumptions (1)--(4), the state-constrained maximum principle provides a costate of bounded variation and
a bounded-variation multiplier associated with the state constraints, together with an integral adjoint relation.
Specializing to \emph{pure} state constraints (no mixed constraints) yields an identity of the form
\cref{eq:adjoint_integral} except that the state-constraint multiplier appears as a BV function $\zeta_i(\cdot)$.
Writing its Stieltjes increment as $d\zeta_i(t)$ and using the BV decomposition, define the nonnegative measure
$\mu_i := -d\zeta_i$; then $\mu_i\ge 0$ and \cref{eq:adjoint_integral} follows.

\smallskip
\noindent\textbf{Step 2 (Maximum condition from needle variations).}
Fix a Lebesgue point $t$ for $(q^\star,u^\star)$ and consider a needle variation
$u_\varepsilon(\cdot)$ that equals $u^\star(\cdot)$ except on a small interval $(t,t+\varepsilon)$ where it is set
to a constant $\bar u\in U$.
Using (A1)--(A2), the first variation of $J$ exists and is linear in $\bar u-u^\star(t)$, while feasibility of
\cref{eq:ocp_state_constraints} is handled by the measure multipliers $\mu_i$.
The necessary condition that the first variation is nonnegative for all $\bar u\in U$ implies
\cref{eq:max_condition} for almost every $t$.

\smallskip
\noindent\textbf{Step 3 (Adjoint equation from state variations + integration by parts).}
Let $\delta q$ be an admissible first-order state variation induced by admissible control variations.
Write the first variation of the Lagrangian functional associated with \cref{eq:ocp_dyn} using a multiplier $p(\cdot)$,
and integrate by parts on each interval of continuity of $p$.
The terms involving the state constraints appear through Stieltjes integrals against $d\zeta_i$, i.e.,
through $\int \nabla c_i(q^\star(t))\,d\zeta_i(t)$; converting to $\mu_i=-d\zeta_i$ yields \cref{eq:adjoint_measure}.

\smallskip
\noindent\textbf{Step 4 (Complementarity/support).}
Because each $\zeta_i(\cdot)$ is constant on interior intervals where $c_i(q^\star(t))>0$,
its Stieltjes increment vanishes there; hence $\mu_i=-d\zeta_i$ only charges times when the constraint is active.
This is exactly \cref{eq:complementarity_measure}.

\smallskip
\noindent\textbf{Step 5 (Reduced Hamiltonian by Legendre--Fenchel conjugacy).}
~Define the \emph{reduced Hamiltonian} (pointwise supremum over $u$)
\begin{equation}
H_{\mathrm{PMP}}(q,p)
:=\sup_{u\in U}\Big\{p^\top A(q)u-\varphi(u)\Big\}+p^\top f(q)-V(q).
\end{equation}
By strict convexity of $\varphi$, the maximizer $u^\star(q,p)$ is unique and satisfies the first-order condition
$\nabla\varphi(u^\star)=A(q)^\top p$ (when $U=\mathbb{R}^d$; for compact $U$ use the argmax form).
Hence $u^\star(q,p)=\nabla\varphi^\ast(A(q)^\top p)$, and Danskin's theorem yields
\[
\begin{aligned}
\nabla_p H_{\mathrm{PMP}}(q,p)&=f(q)+A(q)u^\star(q,p), \\
\nabla_q H_{\mathrm{PMP}}(q,p)&=\big(\nabla_q f(q)\big)^\top p+\big(\nabla_q A(q)\,u^\star(q,p)\big)^\top p-\nabla V(q).    
\end{aligned}
